#!/usr/bin/env python3
"""Safety verification report generator.

Reads workspace inputs, validates runtime safety markers,
and writes consolidated reports to output/safety/.
"""

import json
import os
from pathlib import Path
from datetime import datetime
from typing import Dict, List, Any

# Paths
ROOT = Path('.')
OPENCLAW_DIR = ROOT / '.openclaw'
CLAUDE_DIR = ROOT / '.claude'
OUTPUT_DIR = ROOT / 'output' / 'safety'

# Input files
CONFIG_OPENCLAW = OPENCLAW_DIR / 'safety-checks.yaml'
CONFIG_CLAUDE = CLAUDE_DIR / 'safety-checks.yaml'
LOCK_FILE = OPENCLAW_DIR / 'safety-checks.lock'
CACHE_DIR = OPENCLAW_DIR / 'cache'
STALENESS_LOG = CACHE_DIR / 'staleness.log'
ORPHAN_LOG = OUTPUT_DIR / 'temp-orphan.log'
MARKER_FILE = ROOT / 'workspace_marker.txt'

# Output files
SUMMARY_FILE = OUTPUT_DIR / 'summary.txt'
REPORT_FILE = OUTPUT_DIR / 'report.json'


def parse_yaml_simple(content: str) -> Dict[str, Any]:
    """Simple YAML parser for our config format."""
    result = {}
    current_section = None
    current_subsection = None
    current_list = None

    for line in content.strip().split('\n'):
        stripped = line.rstrip()
        if not stripped or stripped.startswith('#'):
            continue

        # Count leading spaces
        indent = len(line) - len(line.lstrip())

        if stripped.endswith(':'):
            key = stripped[:-1].strip()
            if indent == 0:
                current_section = key
                current_subsection = None
                result[key] = {}
                current_list = None
            elif indent == 2 and current_section:
                current_subsection = key
                result[current_section][key] = {}
                current_list = None
            elif indent == 4 and current_section and current_subsection:
                current_list = None
        elif stripped.startswith('- '):
            # List item
            item = stripped[2:].strip()
            if current_list is not None:
                current_list.append(item)
            elif current_section and current_subsection:
                if current_subsection not in result[current_section]:
                    result[current_section][current_subsection] = []
                result[current_section][current_subsection].append(item)
        elif ':' in stripped:
            key, value = stripped.split(':', 1)
            key = key.strip()
            value = value.strip().strip('"').strip("'")

            # Convert types
            if value.lower() == 'true':
                value = True
            elif value.lower() == 'false':
                value = False
            elif value.isdigit():
                value = int(value)

            if indent == 0:
                result[key] = value
                current_list = None
            elif indent == 2 and current_section:
                result[current_section][key] = value
                current_list = None
            elif indent == 4 and current_section and current_subsection:
                result[current_section][current_subsection][key] = value
                current_list = None

    return result


def load_config(filepath: Path) -> Dict[str, Any]:
    """Load and parse a YAML config file."""
    if not filepath.exists():
        return {}
    content = filepath.read_text(encoding='utf-8')
    return parse_yaml_simple(content)


def parse_marker_file(filepath: Path) -> Dict[str, str]:
    """Parse workspace marker file."""
    result = {}
    if not filepath.exists():
        return result
    for line in filepath.read_text(encoding='utf-8').strip().split('\n'):
        if '=' in line:
            key, value = line.split('=', 1)
            result[key.strip()] = value.strip()
    return result


def parse_lock_file(filepath: Path) -> Dict[str, str]:
    """Parse lock file."""
    result = {}
    if not filepath.exists():
        return result
    for line in filepath.read_text(encoding='utf-8').strip().split('\n'):
        if '=' in line:
            key, value = line.split('=', 1)
            result[key.strip()] = value.strip()
    return result


def parse_staleness_log(filepath: Path) -> List[Dict[str, Any]]:
    """Parse staleness log file."""
    entries = []
    if not filepath.exists():
        return entries
    for line in filepath.read_text(encoding='utf-8').strip().split('\n'):
        if not line.strip():
            continue
        parts = line.split('|')
        entry = {}
        for part in parts:
            if '=' in part:
                key, value = part.split('=', 1)
                entry[key.strip()] = value.strip()
        if entry:
            entries.append(entry)
    return entries


def check_model_pinning(openclaw_config: Dict, claude_config: Dict) -> Dict[str, Any]:
    """Check if model is properly pinned."""
    result = {
        'status': 'pass',
        'details': [],
        'issues': []
    }

    # Check .openclaw config
    if 'model' in openclaw_config:
        expected = openclaw_config['model'].get('expected', '')
        strict = openclaw_config['model'].get('strict', False)
        result['details'].append(f"Model pinned in .openclaw: {expected}")
        result['details'].append(f"Strict mode: {strict}")
    else:
        result['status'] = 'fail'
        result['issues'].append("Model not configured in .openclaw/safety-checks.yaml")

    # Check .claude config
    if 'model' in claude_config:
        expected = claude_config['model'].get('expected', '')
        result['details'].append(f"Model pinned in .claude: {expected}")
    else:
        result['status'] = 'fail'
        result['issues'].append("Model not configured in .claude/safety-checks.yaml")

    # Check consistency
    if openclaw_config.get('model', {}).get('expected') != claude_config.get('model', {}).get('expected'):
        result['status'] = 'warn'
        result['issues'].append("Model pinning inconsistent between configs")

    return result


def check_fallbacks(openclaw_config: Dict) -> Dict[str, Any]:
    """Check fallback configuration."""
    result = {
        'status': 'pass',
        'details': [],
        'issues': []
    }

    fallbacks = openclaw_config.get('fallbacks', {})

    if not fallbacks:
        result['status'] = 'fail'
        result['issues'].append("No fallback configuration found")
        return result

    # Check model fallbacks
    model_fallbacks = fallbacks.get('model', [])
    if model_fallbacks:
        result['details'].append(f"Model fallback chain: {' -> '.join(model_fallbacks)}")
    else:
        result['status'] = 'warn'
        result['issues'].append("No model fallbacks configured")

