    storage_fallbacks = fallbacks.get('storage', [])
    if storage_fallbacks:
        result['details'].append(f"Storage fallback paths: {', '.join(storage_fallbacks)}")
    else:
        result['status'] = 'warn'
        result['issues'].append("No storage fallbacks configured")

    return result


def check_cache_freshness(staleness_entries: List[Dict], ttl_seconds: int) -> Dict[str, Any]:
    """Check cache freshness based on staleness log."""
    result = {
        'status': 'pass',
        'details': [],
        'issues': [],
        'ttl_seconds': ttl_seconds,
        'entries_checked': len(staleness_entries)
    }

    if not staleness_entries:
        result['details'].append("No cache entries found in staleness log")
        return result

    stale_count = 0
    fresh_count = 0

    for entry in staleness_entries:
        name = entry.get('api_response_auth', entry.get('user_preferences', 'unknown'))
        # Extract name from first part before |
        if '|' in str(entry):
            name = str(entry).split('|')[0] if entry else 'unknown'
        else:
            # First key is the name
            name = list(entry.keys())[0] if entry else 'unknown'

        age = int(entry.get('age_seconds', 0))
        status = entry.get('status', 'unknown')

        result['details'].append(f"Cache entry '{name}': {age}s old (status: {status})")

        if age > ttl_seconds or status == 'stale':
            stale_count += 1
            result['issues'].append(f"Stale cache entry: {name} ({age}s > {ttl_seconds}s TTL)")
        else:
            fresh_count += 1

    if stale_count > 0:
        result['status'] = 'warn'

    result['details'].append(f"Summary: {fresh_count} fresh, {stale_count} stale entries")

    return result


def check_session_hygiene(lock_data: Dict, orphan_log_path: Path) -> Dict[str, Any]:
    """Check session hygiene - locks and orphan files."""
    result = {
        'status': 'pass',
        'details': [],
        'issues': []
    }

    # Check for stale lock
    if lock_data:
        marker = lock_data.get('MARKER', '')
        pid = lock_data.get('PID', '')
        result['details'].append(f"Lock file exists (PID={pid})")

        if marker == 'stale-lock':
            result['status'] = 'fail'
            result['issues'].append(f"Stale lock detected: PID={pid} (process may be dead)")
        else:
            result['details'].append(f"Lock marker: {marker}")
    else:
        result['details'].append("No lock file found")

    # Check for orphan temp files
    if orphan_log_path.exists():
        content = orphan_log_path.read_text(encoding='utf-8').strip()
        if content:
            result['status'] = 'fail'
            result['issues'].append(f"Orphan temp file detected: {content}")
        result['details'].append("Temp orphan log exists")
    else:
        result['details'].append("No orphan temp files detected")

    return result


def generate_report(checks: Dict[str, Dict]) -> str:
    """Generate English summary report."""
    lines = [
        "=" * 60,
        "SAFETY VERIFICATION REPORT",
        f"Generated: {datetime.now().isoformat()}",
        "=" * 60,
        ""
    ]

    overall_status = "PASS"

    for check_name, check_result in checks.items():
        status = check_result.get('status', 'unknown').upper()
        if status in ('FAIL', 'WARN'):
            overall_status = status

        lines.append(f"## {check_name.replace('_', ' ').title()}")
        lines.append(f"Status: {status}")

        for detail in check_result.get('details', []):
            lines.append(f"  - {detail}")

        if check_result.get('issues'):
            lines.append("  Issues:")
            for issue in check_result['issues']:
                lines.append(f"    * {issue}")

        lines.append("")

    lines.append("=" * 60)
    lines.append(f"OVERALL STATUS: {overall_status}")
    lines.append("=" * 60)

    return "\n".join(lines)


def main():
    """Main entry point."""
    # Ensure output directory exists
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

    # Load configuration files
    openclaw_config = load_config(CONFIG_OPENCLAW)
    claude_config = load_config(CONFIG_CLAUDE)

    # Load marker file for TTL
    marker_data = parse_marker_file(MARKER_FILE)
    ttl_seconds = int(marker_data.get('CACHE_TTL_SECONDS', 3600))

    # Load lock file
    lock_data = parse_lock_file(LOCK_FILE)

    # Load staleness log
    staleness_entries = parse_staleness_log(STALENESS_LOG)

    # Perform checks
    checks = {
        'model_pinning': check_model_pinning(openclaw_config, claude_config),
        'fallback_configuration': check_fallbacks(openclaw_config),
        'cache_freshness': check_cache_freshness(staleness_entries, ttl_seconds),
        'session_hygiene': check_session_hygiene(lock_data, ORPHAN_LOG)
    }

    # Generate reports
    summary_text = generate_report(checks)

    # JSON report
    json_report = {
        'timestamp': datetime.now().isoformat(),
        'checks': checks,
        'overall_status': 'PASS' if all(c.get('status') == 'pass' for c in checks.values()) else 'FAIL',
        'input_files': {
            'openclaw_config': str(CONFIG_OPENCLAW),
            'claude_config': str(CONFIG_CLAUDE),
            'lock_file': str(LOCK_FILE),
            'staleness_log': str(STALENESS_LOG),
            'orphan_log': str(ORPHAN_LOG),
            'marker_file': str(MARKER_FILE)
        }
    }

    # Write outputs
    SUMMARY_FILE.write_text(summary_text, encoding='utf-8')
    REPORT_FILE.write_text(json.dumps(json_report, indent=2), encoding='utf-8')

    print(f"Reports generated:")
    print(f"  - {SUMMARY_FILE}")
    print(f"  - {REPORT_FILE}")


if __name__ == '__main__':
    main()
